import { Command } from "commander";

import { invoke, type Implementation } from "@gooi/exchange";
import { artifact } from "@gooi/kernel/evidence";
import { commands } from "./commands.js";

async function run(edge: Implementation, input: unknown) {
  try {
    const result = await invoke(edge, artifact(edge.operation.input, input));

    console.log(JSON.stringify(result.artifact.value, null, 2));
  } catch(error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}

const program = new Command("gooi").description("Gooi's own command: slices and tasks");
const sliceCommands = program.command("slice").description("Track gooi's slices; only one is open at a time");

sliceCommands.command("status").description("Show the open slice and the done slices").action((options) => run(commands.slice.commands.status, { ...options }));
sliceCommands.command("open").description("Open the next slice. Only one slice can be open at a time.").requiredOption("--title <title>", "Short name for the slice").option("--detail <detail>", "What the slice covers").requiredOption("--done <done>", "When it can be closed, in terms of real use").action((options) => run(commands.slice.commands.open, { ...options }));
sliceCommands.command("close").description("Close the open slice with what it was used for").requiredOption("--used <used>", "What the slice was actually used for").action((options) => run(commands.slice.commands.close, { ...options }));

const taskCommands = program.command("task").description("Track tasks as Markdown files in tasks/");

taskCommands.command("list").description("List open and done tasks, and any files that can't be read").action((options) => run(commands.task.commands.list, { ...options }));
taskCommands.command("add").description("Add a task as tasks/<name>.md").requiredOption("--title <title>", "One-line title").option("--name <name>", "File name; made from the title when left out").option("--notes <notes>", "Notes written below the title").action((options) => run(commands.task.commands.add, { ...options }));
taskCommands.command("finish").description("Mark a task done, changing only its header").requiredOption("--name <name>", "Task name, or a prefix that matches one task").action((options) => run(commands.task.commands.finish, { ...options }));

const agentCommands = program.command("agent").description("Hand work to an agent; GOOI_AGENT picks its backing (claude or omlx)");

agentCommands.command("tell").description("Tell the agent about work to do, in your own words; it adds the tasks").requiredOption("--text <text>", "What you want, in your own words").action((options) => run(commands.agent.commands.tell, { ...options }));
await program.parseAsync();
